def transform(grid):
    h, w = len(grid), len(grid[0])
    bg = max(set(v for row in grid for v in row), key=lambda v: sum(row.count(v) for row in grid))
    cells = {}
    for r, row in enumerate(grid):
        for c, v in enumerate(row):
            if v != bg:
                cells.setdefault(v, []).append((r, c))
    all_cells = [p for ps in cells.values() for p in ps]
    cr = sum(r for r, c in all_cells) / len(all_cells)
    cc = sum(c for r, c in all_cells) / len(all_cells)
    out = [row[:] for row in grid]
    for color, ps in cells.items():
        pr = sum(r for r, c in ps) / len(ps)
        pc = sum(c for r, c in ps) / len(ps)
        dr = 1 if pr > cr else -1
        dc = 1 if pc > cc else -1
        for r, c in ps:
            while 0 <= r < h and 0 <= c < w:
                out[r][c] = color
                r += dr
                c += dc
    return out

